def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']  # [batch_size, n]
    bsz, n = objective.shape
    if n <= 1:
        empty = (torch.empty(0, dtype=torch.int64, device=objective.device),) * 3
        return PrefBatch(mode='pairwise', pair_idx=empty, weight=None, meta={'builder': 'all_pairs_clamped_gap_masked_no_loop'})
    gap = objective.unsqueeze(2) - objective.unsqueeze(1)  # winner - loser
    valid_mask = gap < 0  # True where winner better
    # Clamp gaps for numerical stability (negative values only)
    clamped_gap = gap.clamp(min=-0.1, max=-1e-5) * valid_mask.to(gap.dtype)
    b_idx, w_idx, l_idx = valid_mask.nonzero(as_tuple=True)
    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx.to(torch.int64), w_idx.to(torch.int64), l_idx.to(torch.int64)),
        weight=None,
        meta={'builder': 'all_pairs_clamped_gap_masked_no_loop'}
    )
